#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MOD 1000000007

int n;
char S[100005], T[100005];
long long dp[100005][2];
long long sum[100005][2];

int main() {
    scanf("%s %s", S, T);
    n = strlen(S);

    // base case: after processing all digits
    dp[n][0] = 1; // tight = 0 means already smaller, so any suffix works
    dp[n][1] = 1; // tight = 1 means exactly equal so far; after last digit, it's valid
    sum[n][0] = 0;
    sum[n][1] = 0;

    for (int i = n - 1; i >= 0; i--) {
        int s_digit = S[i] - '0';

        for (int tight = 0; tight <= 1; tight++) {
            long long ways = 0;
            long long total = 0;

            int max_digit;
            if (tight) max_digit = s_digit;
            else max_digit = 9;

            if (T[i] == '?') {
                for (int d = 0; d <= max_digit; d++) {
                    int next_tight = tight && (d == max_digit && max_digit == s_digit);
                    ways = (ways + dp[i+1][next_tight]) % MOD;
                    long long add = (sum[i+1][next_tight] + d * dp[i+1][next_tight]) % MOD;
                    total = (total + add) % MOD;
                }
            } else {
                int d = T[i] - '0';
                if (d <= max_digit) {
                    int next_tight = tight && (d == s_digit);
                    ways = dp[i+1][next_tight];
                    total = (sum[i+1][next_tight] + d * dp[i+1][next_tight]) % MOD;
                }
                // else ways stays 0, total stays 0
            }

            dp[i][tight] = ways;
            sum[i][tight] = total;
        }
    }

    printf("%lld\n", sum[0][1] % MOD);

    return 0;
}

