#define MOD 1000000007LL

int main() {
    char S[105], T[105];
    scanf("%s %s", S, T);
    int n = strlen(S);

    long long pow10[105];
    pow10[0] = 1;
    for (int i = 1; i <= n; i++)
        pow10[i] = pow10[i-1] * 10 % MOD;

    // dp_count[tight], dp_sum[tight]
    long long cnt[2], sm[2];
    // Base case: position n
    cnt[0] = 1; cnt[1] = 1;
    sm[0] = 0; sm[1] = 0;

    for (int i = n-1; i >= 0; i--) {
        long long new_cnt[2] = {0, 0};
        long long new_sm[2] = {0, 0};
        int s_digit = S[i] - '0';

        for (int t = 0; t <= 1; t++) {
            int lo = 0, hi = 9;
            if (T[i] != '?') {
                lo = hi = T[i] - '0';
            }
            for (int d = lo; d <= hi; d++) {
                if (t && d > s_digit) continue;
                int new_tight = t && (d == s_digit) ? 1 : 0;
                new_cnt[t] = (new_cnt[t] + cnt[new_tight]) % MOD;
                new_sm[t] = (new_sm[t] + (long long)d % MOD * pow10[n-1-i] % MOD * cnt[new_tight] % MOD + sm[new_tight]) % MOD;
            }
        }
        cnt[0] = new_cnt[0]; cnt[1] = new_cnt[1];
        sm[0] = new_sm[0]; sm[1] = new_sm[1];
    }

    // Start with tight=1 (we start equal to S)
    printf("%lld\n", sm[1]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL

static long long mod_pow10(int n) {
    long long r = 1;
    while (n--) r = (r * 10) % MOD;
    return r;
}

int main(void) {
    char S[200005], T[200005];
    if (scanf("%s %s", S, T) != 2) return 0;

    int n = (int)strlen(S);

    long long *pow10 = (long long *)malloc((n + 1) * sizeof(long long));
    long long *sufWays = (long long *)malloc((n + 1) * sizeof(long long));
    long long *sufSum = (long long *)malloc((n + 1) * sizeof(long long));

    pow10[0] = 1;
    for (int i = 1; i <= n; i++) pow10[i] = (pow10[i - 1] * 10) % MOD;

    /* For suffix [i..n-1]:
       sufWays[i] = number of ways to replace ? in T[i..] freely
       sufSum[i]  = sum of all resulting numeric values of suffix strings of length n-i
    */
    sufWays[n] = 1;
    sufSum[n] = 0;

    for (int i = n - 1; i >= 0; i--) {
        int len = n - 1 - i;
        if (T[i] == '?') {
            sufWays[i] = (sufWays[i + 1] * 10) % MOD;
            long long addDigits = 45LL * pow10[len] % MOD; // sum 0..9 = 45
            sufSum[i] = ( (10LL * sufSum[i + 1]) % MOD + (addDigits * sufWays[i + 1]) % MOD ) % MOD;
        } else {
            int d = T[i] - '0';
            sufWays[i] = sufWays[i + 1];
            sufSum[i] = ( (1LL * d * pow10[len]) % MOD * sufWays[i + 1] + sufSum[i + 1] ) % MOD;
        }
    }

    long long ans = 0;
    int equalPossible = 1; // whether prefix can still be equal to S so far

    for (int i = 0; i < n; i++) {
        if (!equalPossible) break;

        int s = S[i] - '0';
        int len = n - 1 - i;

        if (T[i] == '?') {
            // Choose a digit smaller than s here, then suffix can be anything
            if (s > 0) {
                long long cntSmall = s; // digits 0..s-1
                long long sumSmallDigits = 1LL * s * (s - 1) / 2 % MOD;

                long long part = 0;
                part = (part + (sumSmallDigits * pow10[len]) % MOD * sufWays[i + 1]) % MOD;
                part = (part + (cntSmall % MOD) * sufSum[i + 1]) % MOD;
                ans = (ans + part) % MOD;
            }
            // Keep equal by choosing digit s
            equalPossible = 1;
        } else {
            int d = T[i] - '0';
            if (d < s) {
                // Prefix already smaller here, suffix free
                long long part = ( (1LL * d * pow10[len]) % MOD * sufWays[i + 1] + sufSum[i + 1] ) % MOD;
                ans = (ans + part) % MOD;
                equalPossible = 0;
            } else if (d == s) {
                equalPossible = 1;
            } else {
                equalPossible = 0;
            }
        }
    }

    // If entire string can be equal to S, include that one completion
    if (equalPossible) {
        ans = (ans + sufSum[0]) % MOD;
    }

    printf("%lld\n", ans % MOD);

    free(pow10);
    free(sufWays);
    free(sufSum);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S, T;
    cin >> S >> T;
    int n = S.size();

    // dp[pos][tight] = {count, sum}
    // tight = 0 means already less, tight = 1 means still equal so far
    vector<vector<pair<int64, int64>>> dp(n + 1, vector<pair<int64, int64>>(2));
    dp[0][1] = {1, 0}; // one way with sum 0 at start, still equal

    for (int i = 0; i < n; i++) {
        for (int tight = 0; tight < 2; tight++) {
            auto [cnt, sum] = dp[i][tight];
            if (cnt == 0) continue;
            int s_digit = S[i] - '0';
            int lo = 0, hi = 9;
            if (T[i] != '?') {
                lo = hi = T[i] - '0';
            }
            for (int d = lo; d <= hi; d++) {
                int ntight = tight;
                if (ntight && d > s_digit) continue;
                if (ntight && d < s_digit) ntight = 0;
                dp[i+1][ntight].first = (dp[i+1][ntight].first + cnt) % MOD;
                dp[i+1][ntight].second = (dp[i+1][ntight].second + (sum * 10 % MOD + d * cnt % MOD)) % MOD;
            }
        }
    }

    int64 ans = (dp[n][0].second + dp[n][1].second) % MOD;
    cout << ans << "\n";

    return 0;
}

