const int MOD = 1e9 + 7;

int n;
string S, T;
long long pw[205]; // powers of 10

// returns {count, sum}
pair<long long,long long> dp[205][2];
bool visited[205][2];

pair<long long,long long> solve(int i, int tight) {
    if (i == n) return {1, 0};
    if (visited[i][tight]) return dp[i][tight];
    visited[i][tight] = true;

    long long cnt = 0, sm = 0;
    int lo = 0, hi = 9;
    if (T[i] != '?') { lo = hi = T[i] - '0'; }

    for (int d = lo; d <= hi; d++) {
        int new_tight;
        if (tight) {
            int sd = S[i] - '0';
            if (d > sd) continue;
            new_tight = (d == sd) ? 1 : 0;
        } else {
            new_tight = 0;
        }
        auto [c, s] = solve(i+1, new_tight);
        cnt = (cnt + c) % MOD;
        sm = (sm + (1LL * d % MOD * pw[n-1-i] % MOD * c % MOD + s) % MOD) % MOD;
    }

    dp[i][tight] = {cnt, sm};
    return {cnt, sm};
}

