static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S, T;
    cin >> S >> T;
    int n = (int)S.size();

    // dpLessCnt: number of ways for processed prefix where T' prefix < S prefix
    // dpLessSum: sum of numeric values contributed by processed prefix among those ways
    // dpEqCnt: number of ways where processed prefix == S prefix
    // dpEqSum: sum of numeric values contributed by processed prefix among those ways
    long long dpLessCnt = 0, dpLessSum = 0;
    long long dpEqCnt = 1, dpEqSum = 0;

    for (int i = 0; i < n; ++i) {
        vector<int> digits;
        if (T[i] == '?') {
            digits.resize(10);
            iota(digits.begin(), digits.end(), 0);
        } else {
            digits.push_back(T[i] - '0');
        }

        long long nLessCnt = 0, nLessSum = 0;
        long long nEqCnt = 0, nEqSum = 0;
        int s = S[i] - '0';

        // Transition from already-less state: any allowed digit keeps it less
        if (dpLessCnt != 0 || dpLessSum != 0) {
            for (int d : digits) {
                nLessCnt = (nLessCnt + dpLessCnt) % MOD;
                nLessSum = (nLessSum + (dpLessSum * 10 + dpLessCnt * d) % MOD) % MOD;
            }
        }

        // Transition from equal state
        if (dpEqCnt != 0 || dpEqSum != 0) {
            for (int d : digits) {
                if (d < s) {
                    nLessCnt = (nLessCnt + dpEqCnt) % MOD;
                    nLessSum = (nLessSum + (dpEqSum * 10 + dpEqCnt * d) % MOD) % MOD;
                } else if (d == s) {
                    nEqCnt = (nEqCnt + dpEqCnt) % MOD;
                    nEqSum = (nEqSum + (dpEqSum * 10 + dpEqCnt * d) % MOD) % MOD;
                }
            }
        }

        dpLessCnt = nLessCnt;
        dpLessSum = nLessSum;
        dpEqCnt = nEqCnt;
        dpEqSum = nEqSum;
    }

    long long ans = (dpLessSum + dpEqSum) % MOD;
    cout << ans % MOD << '\n';
    return 0;
}

