from functools import lru_cache

def solve():
    MOD = 10**9 + 7
    S = input().strip()
    T = input().strip()
    n = len(S)

    S_digits = [int(c) for c in S]

    @lru_cache(maxsize=None)
    def dp(i, tight):
        # returns (count, sum_of_values)
        if i == n:
            return (1, 0)

        if T[i] == '?':
            if tight:
                choices = range(0, S_digits[i] + 1)
            else:
                choices = range(0, 10)
        else:
            d = int(T[i])
            if tight and d > S_digits[i]:
                return (0, 0)
            choices = [d]

        total_count = 0
        total_sum = 0

        for d in choices:
            if tight:
                new_tight = (d == S_digits[i])
            else:
                new_tight = False

            c, s = dp(i + 1, new_tight)

            # digit d at position i contributes d * 10^(n-1-i) * c to the sum
            power = pow(10, n - 1 - i, MOD)
            contrib = (d * power % MOD) * c % MOD

            total_count = (total_count + c) % MOD
            total_sum = (total_sum + contrib + s) % MOD

        return (total_count, total_sum)

    count, result = dp(0, True)
    print(result % MOD)

