import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        String T = sc.next();
        sc.close();

        int n = S.length();

        long[] pow10 = new long[n + 1];
        long[] pow10sum = new long[n + 1]; // sum of 10^k for remaining positions
        pow10[0] = 1;
        pow10sum[0] = 0;
        for (int i = 1; i <= n; i++) {
            pow10[i] = (pow10[i-1] * 10) % MOD;
            pow10sum[i] = (pow10sum[i-1] + pow10[i-1]) % MOD;
        }

        long sumLess = 0;
        long countEqual = 1; // number of ways we are exactly equal so far

        for (int i = 0; i < n; i++) {
            int sDigit = S.charAt(i) - '0';
            char tChar = T.charAt(i);
            int remaining = n - i - 1;

            if (tChar == '?') {
                // case 1: choose digit < sDigit
                long waysLess = sDigit; // digits 0..sDigit-1
                if (waysLess > 0) {
                    long add = (countEqual * waysLess) % MOD;
                    // each such prefix yields sum of all possibilities for remaining positions
                    long baseValue = (add * pow10[remaining]) % MOD;
                    long sumPart = (baseValue + add * pow10sum[remaining] % MOD) % MOD;
                    sumLess = (sumLess + sumPart) % MOD;
                }
                // case 2: choose digit == sDigit
                // countEqual stays the same (multiply by 1)
                // nothing added to sumLess yet
            } else {
                int tDigit = tChar - '0';
                if (tDigit < sDigit) {
                    // all equal so far, now this digit is less -> all remaining free
                    long add = countEqual;
                    long baseValue = (add * pow10[remaining]) % MOD;
                    long sumPart = (baseValue + add * pow10sum[remaining] % MOD) % MOD;
                    sumLess = (sumLess + sumPart) % MOD;
                    countEqual = 0; // no longer equal
                } else if (tDigit > sDigit) {
                    countEqual = 0; // invalid
                    break;
                }
                // if equal, continue
            }
        }

        // If countEqual > 0, we have exactly one matching number (the one equal to S)
        if (countEqual > 0) {
            long val = 0;
            for (int i = 0; i < n; i++) {
                val = (val * 10 + (S.charAt(i) - '0')) % MOD;
            }
            sumLess = (sumLess + val) % MOD;
        }

        System.out.println(sumLess % MOD);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String S = fs.next();
        String T = fs.next();

        int n = S.length();
        long[] pow10 = new long[n + 1];
        pow10[0] = 1;
        for (int i = 1; i <= n; i++) pow10[i] = (pow10[i - 1] * 10) % MOD;

        // dpCount[tight]: number of ways for processed prefix
        // dpSum[tight]: total sum of numeric values contributed by processed digits
        long[] dpCount = new long[2];
        long[] dpSum = new long[2];
        dpCount[1] = 1; // initially equal to S on empty prefix

        for (int i = 0; i < n; i++) {
            long[] nextCount = new long[2];
            long[] nextSum = new long[2];

            int sDigit = S.charAt(i) - '0';
            char tc = T.charAt(i);

            int from = 0, to = 9;
            if (tc != '?') {
                from = to = tc - '0';
            }

            long place = pow10[n - 1 - i];

            for (int tight = 0; tight <= 1; tight++) {
                long cnt = dpCount[tight];
                long sum = dpSum[tight];
                if (cnt == 0 && sum == 0) continue;

                if (tight == 0) {
                    // Already smaller, any allowed digit works
                    int k = to - from + 1;
                    long ways = k;
                    long digitSum = ((long)(from + to) * k / 2) % MOD;

                    nextCount[0] = (nextCount[0] + cnt * ways) % MOD;
                    nextSum[0] = (nextSum[0]
                            + sum * ways
                            + cnt * digitSum % MOD * place) % MOD;
                } else {
                    // Must keep <= S at this digit
                    for (int d = from; d <= to; d++) {
                        if (d > sDigit) continue;
                        int nt = (d == sDigit) ? 1 : 0;
                        nextCount[nt] = (nextCount[nt] + cnt) % MOD;
                        nextSum[nt] = (nextSum[nt] + sum + cnt * d % MOD * place) % MOD;
                    }
                }
            }

            dpCount = nextCount;
            dpSum = nextSum;
        }

        long ans = (dpSum[0] + dpSum[1]) % MOD;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}
